(6241206, 923050, 37845, '<td valign="top">Hope your score is doing well :)</td>', 'Hope your score is doing well :)', '2010-12-01 21:43:44.000000', NULL, 1),
(6241208, 922474, 96751, '<td valign="top">Oh my goodness.  This hurts it''s so good.  How unique and unusual and wonderful.  Very interesting technique and pov, and the glorious lavender and white and black tones.  My pick for the blue.</td>', 'Oh my goodness.  This hurts it''s so good.  How unique and unusual and wonderful.  Very interesting technique and pov, and the glorious lavender and white and black tones.  My pick for the blue.', '2010-12-01 21:45:22.000000', NULL, 1),
(6241259, 923171, 40391, '<td valign="top">Great pose and location.  I feel the lighting on her is a little harsh but I guess if it was reduced it may take away some of the impact youve produced.</td>', 'Great pose and location.  I feel the lighting on her is a little harsh but I guess if it was reduced it may take away some of the impact youve produced.', '2010-12-01 23:21:27.000000', NULL, 1),
(6241262, 921564, 40391, '<td valign="top">A nice serene scene with lovely colours.  I particularly like the foreground.  I find the blown area around the sun a little painful to view though.</td>', 'A nice serene scene with lovely colours.  I particularly like the foreground.  I find the blown area around the sun a little painful to view though.', '2010-12-01 23:23:50.000000', NULL, 1),
(6241265, 922701, 40391, '<td valign="top">Nice capture of his pose.  He looks very regal.  The sticks are a little distracting but I guess there wasnt much you could do about that.</td>', 'Nice capture of his pose.  He looks very regal.  The sticks are a little distracting but I guess there wasnt much you could do about that.', '2010-12-01 23:25:41.000000', NULL, 1),
(6241269, 921870, 40391, '<td valign="top">At first I thought this was a bit boring with nice colours.  I can see now that youre trying to tell a story which Im guessing the book is a real tear-jerker that makes the shot so much more interesting.</td>', 'At first I thought this was a bit boring with nice colours.  I can see now that youre trying to tell a story which Im guessing the book is a real tear-jerker that makes the shot so much more interesting.', '2010-12-01 23:27:57.000000', NULL, 1),
(6241273, 921988, 40391, '<td valign="top">Wow! Talk about in your face.  Thats a great expression and action youve captured which I hope ended well :-)</td>', 'Wow! Talk about in your face.  Thats a great expression and action youve captured which I hope ended well :-)', '2010-12-01 23:29:34.000000', NULL, 1),
(6241279, 922313, 40391, '<td valign="top">A beautiful scene well captured and processed.  Its a pity that you missed cloning the sensor dust in the left part of the sky as I keep going to it when I look at this image.  Overall I quite like this.</td>', 'A beautiful scene well captured and processed.  Its a pity that you missed cloning the sensor dust in the left part of the sky as I keep going to it when I look at this image.  Overall I quite like this.', '2010-12-01 23:32:03.000000', NULL, 1),
(6241287, 921899, 40391, '<td valign="top">Im sure theres an interesting story behind this shot.  The setup is lovely but I feel the exposure was slightly too long or the ISO too high.  There is too much light on his face and the brightness of the bulbs in the background are too distracting.  The shot is still good enough to attract my attention.</td>', 'Im sure theres an interesting story behind this shot.  The setup is lovely but I feel the exposure was slightly too long or the ISO too high.  There is too much light on his face and the brightness of the bulbs in the background are too distracting.  The shot is still good enough to attract my attention.', '2010-12-01 23:36:47.000000', NULL, 1),
(6241320, 922937, 40391, '<td valign="top">This is such an intriguing shot.  I love the way youve captured the couple while getting so much movement around them.  The splashes of red an blue are beautiful.  Very impressive.</td>', 'This is such an intriguing shot.  I love the way youve captured the couple while getting so much movement around them.  The splashes of red an blue are beautiful.  Very impressive.', '2010-12-01 23:39:00.000000', NULL, 1),
(6241348, 922972, 40391, '<td valign="top">A very interesting shot made pleasant by the good lighting and constant green.</td>', 'A very interesting shot made pleasant by the good lighting and constant green.', '2010-12-01 23:40:49.000000', NULL, 1),
(6241360, 923127, 40391, '<td valign="top">I wouldnt say this shot was very well captured but the colour, motion and subjects make for a very interesting image.  I like!</td>', 'I wouldnt say this shot was very well captured but the colour, motion and subjects make for a very interesting image.  I like!', '2010-12-01 23:43:32.000000', NULL, 1),
(6241379, 918888, 32145, '<td valign="top">Great. I''d love to see this hi-res</td>', 'Great. I''d love to see this hi-res', '2010-12-02 00:05:10.000000', NULL, 1),
(6241391, 923156, 16241, '<td valign="top">vintage, cute shot</td>', 'vintage, cute shot', '2010-12-02 00:18:28.000000', NULL, 1),
