(6241523, 922472, 40391, '<td valign="top">A warm moment beautifully captured.  The softness of the background makes this image work so well.</td>', 'A warm moment beautifully captured.  The softness of the background makes this image work so well.', '2010-12-02 02:07:24.000000', NULL, 1),
(6241526, 922450, 40391, '<td valign="top">Very cute and lovely location.  A shot with his mouth closed may have even been better. Oh, yes  Happy Birthday little man.</td>', 'Very cute and lovely location.  A shot with his mouth closed may have even been better. Oh, yes  Happy Birthday little man.', '2010-12-02 02:09:46.000000', NULL, 1),
(6241529, 922584, 40391, '<td valign="top">And a stunning lake as well.  Very nicely composed.</td>', 'And a stunning lake as well.  Very nicely composed.', '2010-12-02 02:11:10.000000', NULL, 1),
