(6241547, 923028, 40391, '<td valign="top">Simple yet stunning!  And that would have to be the sharpest horizon Ive ever seen.</td>', 'Simple yet stunning!  And that would have to be the sharpest horizon Ive ever seen.', '2010-12-02 02:24:02.000000', NULL, 1),
(6241548, 922996, 40391, '<td valign="top">A very beautiful and well composed image.  The softness and lighting works so well for me.</td>', 'A very beautiful and well composed image.  The softness and lighting works so well for me.', '2010-12-02 02:25:33.000000', NULL, 1),
