(6241571, 921469, 40391, '<td valign="top">It is a beautiful waterfall but I would loved to have seen this shot taken at a slower speed to get more details from the rocks and a smooth flow from the water.  But thats just me.</td>', 'It is a beautiful waterfall but I would loved to have seen this shot taken at a slower speed to get more details from the rocks and a smooth flow from the water.  But thats just me.', '2010-12-02 03:30:48.000000', NULL, 1),
(6241573, 922979, 40391, '<td valign="top">A beautiful soft image.  I would like to know how you achieved it.</td>', 'A beautiful soft image.  I would like to know how you achieved it.', '2010-12-02 03:34:53.000000', NULL, 1),
