INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6244046, 922738, 50695, '<td valign="top">are you sure you can''t crop off everything behind that guy sitting in the middle?</td>', 'are you sure you can''t crop off everything behind that guy sitting in the middle?', '2010-12-04 00:47:23.000000', NULL, 1),
(6244047, 922943, 108580, '<td valign="top">LOL, that one gull at the front... the rest all watching the show.</td>', 'LOL, that one gull at the front... the rest all watching the show.', '2010-12-04 00:51:41.000000', NULL, 1),
(6244050, 921164, 108580, '<td valign="top">Very emotional and sad image. How those flies survive in a desert is anyones guess. Photography is a very powerful medium indeed.</td>', 'Very emotional and sad image. How those flies survive in a desert is anyones guess. Photography is a very powerful medium indeed.', '2010-12-04 01:02:17.000000', NULL, 1),
(6244053, 918888, 108580, '<td valign="top">Very creative...well done. Crisp neat emotional sensational.</td>', 'Very creative...well done. Crisp neat emotional sensational.', '2010-12-04 01:03:42.000000', NULL, 1),
(6244081, 920638, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: An image at the threshold - I''ve looked at it on my laptop and I see the moon and a few branches and something occluding the moon on the left. Then I tilt my screen and the whole scene emerges. That is somewhat interesting.<br/> <br/>Critical stuff: The above (in my view) is not enough. The overall enjoyability of the image is quite low.<br/> <br/>Overall: I can appreciate the minimalistic thing going on here but in the final analysis I''m not really a fan.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: An image at the threshold - I''ve looked at it on my laptop and I see the moon and a few branches and something occluding the moon on the left. Then I tilt my screen and the whole scene emerges. That is somewhat interesting. Critical stuff: The above (in my view) is not enough. The overall enjoyability of the image is quite low. Overall: I can appreciate the minimalistic thing going on here but in the final analysis I''m not really a fan.', '2010-12-04 03:32:05.000000', NULL, 1),
(6244089, 918371, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Great composition, lighting and model - I like the subtle coloration too. The make up is great.<br/> <br/>Critical stuff: I think the low contrast detracts from the image a great deal and the strange patchy brownish hues are (in my view) quite ruinous.<br/> <br/>Overall: Potentially a great image but ruined I feel by the stuff I''ve mentioned above.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Great composition, lighting and model - I like the subtle coloration too. The make up is great. Critical stuff: I think the low contrast detracts from the image a great deal and the strange patchy brownish hues are (in my view) quite ruinous. Overall: Potentially a great image but ruined I feel by the stuff I''ve mentioned above.', '2010-12-04 03:42:43.000000', NULL, 1),
(6244090, 922272, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: How bizarre! A good thing! I like the coloration, the blur and I very much like the emerging green fence behind the subject.<br/> <br/>Critical stuff: To my eye the composition is suboptimal, I''d have cropped a bit more from the right side I think; having said that, the slight unbalancing of the composition does contribute to a general uneasiness which suits the over feel of the image. The eyes... again mixed feelings - I don''t like them being so prominent, the effect is out of kilter with the rest of the image. Having said that, I can''t deny they draw you in and almost define the image. The question is - do they over-define? I''m undecided.<br/> <br/>Overall: A fascinating image full of unusual (but influential) choices. I like how your image make me (the viewer) deal with it on your terms.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: How bizarre! A good thing! I like the coloration, the blur and I very much like the emerging green fence behind the subject. Critical stuff: To my eye the composition is suboptimal, I''d have cropped a bit more from the right side I think; having said that, the slight unbalancing of the composition does contribute to a general uneasiness which suits the over feel of the image. The eyes... again mixed feelings - I don''t like them being so prominent, the effect is out of kilter with the rest of the image. Having said that, I can''t deny they draw you in and almost define the image. The question is - do they over-define? I''m undecided. Overall: A fascinating image full of unusual (but influential) choices. I like how your image make me (the viewer) deal with it on your terms.', '2010-12-04 03:51:25.000000', NULL, 1),
(6244093, 923127, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: A highly interesting scene - I can see why you''d want to get a shot of this. I think your composition / aspect ratio works really well and the eye is led very nicely around the image.<br/> <br/>Critical stuff: The image is a bit weak technically - all down to the low light? Is that a bit of movement unsharpness I''m seeing. The dragon probably carries it off but the lady is more problematical.<br/> <br/>Overall: A great scene, well captured but technical limitations have placed a cap on overall quality.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: A highly interesting scene - I can see why you''d want to get a shot of this. I think your composition / aspect ratio works really well and the eye is led very nicely around the image. Critical stuff: The image is a bit weak technically - all down to the low light? Is that a bit of movement unsharpness I''m seeing. The dragon probably carries it off but the lady is more problematical. Overall: A great scene, well captured but technical limitations have placed a cap on overall quality.', '2010-12-04 04:00:52.000000', NULL, 1),
(6244096, 923198, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: I like the ambiguity here - it could be a vertical surface with graffiti or a horizontal surface with shadows (perhaps barbed wire loops). I like the texture and toning too. Best of all I like the subtle differences in the three surface zones.<br/> <br/>Critical stuff: I like these textual pieces but I think they have an implicit cap on the amount of interest they hold for viewers.<br/> <br/>Overall: Nice enough but probably lacking enough story to be truly interesting.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: I like the ambiguity here - it could be a vertical surface with graffiti or a horizontal surface with shadows (perhaps barbed wire loops). I like the texture and toning too. Best of all I like the subtle differences in the three surface zones. Critical stuff: I like these textual pieces but I think they have an implicit cap on the amount of interest they hold for viewers. Overall: Nice enough but probably lacking enough story to be truly interesting.', '2010-12-04 04:08:54.000000', NULL, 1),
