(6247905, 923140, 65234, '<td valign="top">There is a softness to this which is contradicted by the intensity of the cat''s stare.  Otherwise one would be tempted to call him pettably soft.</td>', 'There is a softness to this which is contradicted by the intensity of the cat''s stare.  Otherwise one would be tempted to call him pettably soft.', '2010-12-07 22:53:25.000000', NULL, 1),
(6247906, 922807, 67697, '<td valign="top">well there he is - i''m assuming from your ribbon winning pic.  i bet he is a lot of fun.  it looks like he''s giving off the grumpy little toddler look.  cute!</td>', 'well there he is - i''m assuming from your ribbon winning pic.  i bet he is a lot of fun.  it looks like he''s giving off the grumpy little toddler look.  cute!', '2010-12-07 22:53:34.000000', NULL, 1),
(6247907, 922584, 65234, '<td valign="top">Quite beautiful; lots to see everywhere I look, but still tranquil and serene in mood.</td>', 'Quite beautiful; lots to see everywhere I look, but still tranquil and serene in mood.', '2010-12-07 22:54:29.000000', NULL, 1),
