(6247919, 923175, 65234, '<td valign="top">Nice light; looks like they were enjoying the snow.  Think I might have cropped more tightly on top on this one.</td>', 'Nice light; looks like they were enjoying the snow.  Think I might have cropped more tightly on top on this one.', '2010-12-07 22:56:16.000000', NULL, 1),
(6247923, 922662, 65234, '<td valign="top">Beautiful detail and expression.</td>', 'Beautiful detail and expression.', '2010-12-07 22:58:11.000000', NULL, 1),
(6247924, 921740, 65234, '<td valign="top">Adorable capture :-)</td>', 'Adorable capture :-)', '2010-12-07 22:58:27.000000', NULL, 1),
(6247925, 922049, 65234, '<td valign="top">Gives me a real sense of sitting peacefully on a beach for hours, doing nothing more than watching the slow motion of the stars and listening to the regular sounds of the waves coming and going.  So peaceful.</td>', 'Gives me a real sense of sitting peacefully on a beach for hours, doing nothing more than watching the slow motion of the stars and listening to the regular sounds of the waves coming and going.  So peaceful.', '2010-12-07 23:00:19.000000', NULL, 1),
