(6247927, 922749, 65234, '<td valign="top">Love the light and perspective.  Makes the snake look quite evil.</td>', 'Love the light and perspective.  Makes the snake look quite evil.', '2010-12-07 23:00:50.000000', NULL, 1),
(6247928, 921861, 67697, '<td valign="top">Spooky.  Has almost a sci-fi quality to it.</td>', 'Spooky.  Has almost a sci-fi quality to it.', '2010-12-07 23:01:40.000000', NULL, 1),
