INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6248753, 923142, 12250, '<td valign="top">Very nice.  Thank you for your kind comments!  <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by xianart:</b></div><hr/><i> <a href="//www.dpchallenge.com/image.php?IMAGE_ID=657241" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657241.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657241.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657241.jpg"/></a> You got an X-Prize for my highest rated shots that placed lowest on the final tally!<br/> <br/>A sorely underrated image.  The hint of a victim, the blur, the macro close up and strong linear elements of the ''teeth'' (what are they called?) all combine to create a powerfully oppressive feeling, claustrophobic and shivery.  Nicely done. </i></td></tr></table></td>', 'Very nice.  Thank you for your kind comments!  Originally posted by xianart:  You got an X-Prize for my highest rated shots that placed lowest on the final tally! A sorely underrated image.  The hint of a victim, the blur, the macro close up and strong linear elements of the ''teeth'' (what are they called?) all combine to create a powerfully oppressive feeling, claustrophobic and shivery.  Nicely done. ', '2010-12-08 09:31:02.000000', NULL, 0),
(6248755, 922341, 113278, '<td valign="top">Beautiful shot, congrats on the blue. I love the closer crop you posted as well, really nice stuff.</td>', 'Beautiful shot, congrats on the blue. I love the closer crop you posted as well, really nice stuff.', '2010-12-08 09:33:28.000000', NULL, 0),
