(6277468, 922292, 19936, '<td valign="top">Wow! Somehow I missed this one while I was away.  Congrats on your first ribbon with a well done shot.</td>', 'Wow! Somehow I missed this one while I was away.  Congrats on your first ribbon with a well done shot.', '2011-01-09 14:46:46.000000', NULL, 0),
(6280528, 922826, 94815, '<td valign="top">This is technically a very good shot of an attractive subject but sometimes the placement of the subject in the composition deflates the impact. To my eye, it needs either a slight crop off of the left to give it an elegent portrait look, or a crop off the right to get rid of some of the free atmosphere and let the animal be more claustrophobic and menacing. I''m a softy and would probably opt for the portrait approach (it really is a beautiful animal). Use the Renaissance portrait technique as a guide, locating the inner eye (right eye in this case) on the center line by cropping as first suggested. These proposals reflect my own sensitivities and quite a bit of art study back when I had more time, and may not be the most creative or dynamic solutions. I just thought I would try to help with some ideas for future consideration.</td>', 'This is technically a very good shot of an attractive subject but sometimes the placement of the subject in the composition deflates the impact. To my eye, it needs either a slight crop off of the left to give it an elegent portrait look, or a crop off the right to get rid of some of the free atmosphere and let the animal be more claustrophobic and menacing. I''m a softy and would probably opt for the portrait approach (it really is a beautiful animal). Use the Renaissance portrait technique as a guide, locating the inner eye (right eye in this case) on the center line by cropping as first suggested. These proposals reflect my own sensitivities and quite a bit of art study back when I had more time, and may not be the most creative or dynamic solutions. I just thought I would try to help with some ideas for future consideration.', '2011-01-11 23:04:23.000000', NULL, 0),
(6283830, 921376, 1897, '<td valign="top">Interesting and dynamic composition.  The color and lighting are fantastic.</td>', 'Interesting and dynamic composition.  The color and lighting are fantastic.', '2011-01-15 10:50:44.000000', NULL, 0),
