(6293828, 923018, 113419, '<td valign="top">Lovely</td>', 'Lovely', '2011-01-25 16:05:24.000000', NULL, 0),
(6296134, 923021, 60047, '<td valign="top">Great work, Harold.</td>', 'Great work, Harold.', '2011-01-27 22:55:57.000000', NULL, 0),
(6303802, 922962, 108069, '<td valign="top">Hot damn this is a killer photo. Incredible.</td>', 'Hot damn this is a killer photo. Incredible.', '2011-02-05 18:58:05.000000', NULL, 0),
(6319029, 922292, 17507, '<td valign="top">Ah man! I took a break from DPC for a while, and of course it was during this time that you finally make it to the front page. I knew it would happen sooner or later! Congratulations for your well-deserved recognition for an excellent photo. The depth of field and the crisp focus really bring this Gothic library to life. Well done, sir.</td>', 'Ah man! I took a break from DPC for a while, and of course it was during this time that you finally make it to the front page. I knew it would happen sooner or later! Congratulations for your well-deserved recognition for an excellent photo. The depth of field and the crisp focus really bring this Gothic library to life. Well done, sir.', '2011-02-17 17:08:42.000000', NULL, 0);
